namespace AkilliKisayol {
 [DataContract] public sealed class ModelOptions {
  [DataMember] public bool Remote;
  [DataMember] public string Endpoint="http://localhost:1234/v1/";
  [DataMember] public string Model="";
  [DataMember(EmitDefaultValue=false)] public string ProtectedKey;
  [DataMember] public bool StructuredOutput=true;
  [DataMember] public bool FastMode=true;
  [DataMember] public int MaxOutputTokens=2048;
  public int TokenBudget {get{return MaxOutputTokens<=0?2048:Math.Max(256,Math.Min(32768,MaxOutputTokens));}}
  public ModelOptions Copy(){return (ModelOptions)MemberwiseClone();}
  public string ApiKey {get{if(string.IsNullOrEmpty(ProtectedKey))return "";try{return Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(ProtectedKey),null,DataProtectionScope.CurrentUser));}catch(CryptographicException){return "";}catch(FormatException){return "";}}set{ProtectedKey=string.IsNullOrEmpty(value)?null:Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(value),null,DataProtectionScope.CurrentUser));}}
  public Uri BaseUri(){string address=(Endpoint??"").Trim().TrimEnd('/');if(address.EndsWith("/chat/completions",StringComparison.OrdinalIgnoreCase))address=address.Substring(0,address.Length-17);Uri uri;if(!Uri.TryCreate(address+"/",UriKind.Absolute,out uri)||(uri.Scheme!="http"&&uri.Scheme!="https")||!string.IsNullOrEmpty(uri.UserInfo)||!string.IsNullOrEmpty(uri.Query)||!string.IsNullOrEmpty(uri.Fragment))throw new ArgumentException("Enter an HTTP(S) API base URL, for example http://localhost:1234/v1/.");return uri;}
  public string Validate(string file){if(Remote){try{BaseUri();}catch(ArgumentException e){return e.Message;}if(string.IsNullOrWhiteSpace(Model))return "Enter the model ID exposed by your server.";}else if(string.IsNullOrWhiteSpace(ModelFiles.Resolve(file))||!File.Exists(ModelFiles.Resolve(file)))return "Choose an existing GGUF model file.";return null;}
  public string Describe(string file){if(Remote)return Model+" • "+Endpoint;string selected=ModelFiles.Resolve(file);return string.IsNullOrWhiteSpace(selected)?"No model selected":Path.GetFileName(selected);}
 }
