  void RefreshModels(){var files=ModelFiles.Candidates(modelRoot);if(string.IsNullOrWhiteSpace(path.Text)&&files.Length==1)path.Text=files[0];folderStatus.Text=files.Length==0?"No GGUF files in models yet. Download a GGUF and copy it into this folder.":files.Length==1?"1 GGUF file found. Your selected file is kept.":files.Length+" GGUF files found. Use Browse GGUF to choose; your selected file is kept.";}
  void OpenFolder(){try{Directory.CreateDirectory(ModelFiles.DirectoryFor(modelRoot));Process.Start(new ProcessStartInfo(ModelFiles.DirectoryFor(modelRoot)){UseShellExecute=true});}catch(Exception error){feedback.Text="Could not open models folder: "+error.Message+" Use Browse GGUF to select a file elsewhere.";}}
  void BrowseModel(){var folder=ModelFiles.DirectoryFor(modelRoot);string selected=ModelFiles.Resolve(path.Text,modelRoot,"");var picker=new OpenFileDialog{Filter="GGUF model (*.gguf)|*.gguf",InitialDirectory=File.Exists(selected)?Path.GetDirectoryName(selected):Directory.Exists(folder)?folder:modelRoot};if(picker.ShowDialog(this)==true)path.Text=picker.FileName;}
  internal string SelectedFileForTest {get{return path.Text;}set{path.Text=value;}}
  internal string FolderStatusForTest {get{return folderStatus.Text;}}
  internal void RefreshModelsForTest(){RefreshModels();}
  void Refresh(){local.Visibility=provider.SelectedIndex==0?Visibility.Visible:Visibility.Collapsed;remote.Visibility=provider.SelectedIndex==1?Visibility.Visible:Visibility.Collapsed;}
  internal void CommitForTest(){Commit();}
  internal string FeedbackForTest {get{return feedback.Text;}}
  void Commit(){try{var draft=original.Copy();draft.Remote=provider.SelectedIndex==1;draft.Endpoint=endpoint.Text.Trim();draft.Model=model.Text.Trim();draft.StructuredOutput=structured.IsChecked==true;draft.FastMode=fast.IsChecked==true;draft.MaxOutputTokens=tokens.SelectedItem is int?(int)tokens.SelectedItem:2048;string file=ModelFiles.Resolve(path.Text.Trim(),modelRoot,"");string error=draft.Validate(file);if(error!=null){feedback.Text=error;return;}draft.ApiKey=key.Password;Result=draft;ModelPath=ModelFiles.Portable(file,modelRoot);DialogResult=true;}catch(ArgumentException error){feedback.Text="Invalid model path or setting: "+error.Message;}}
 }
